  font-size: 17px;
  color: var(--color-secondary);
  margin-top: 6px;
  line-height: 1.4;
}
.section-promo {
  font-size: 14px;
  color: var(--color-secondary);
  margin-top: 10px;
}
.section-promo a { color: var(--color-blue); }

/* ===== CAROUSEL ===== */
.carousel-wrapper {
  position: relative;
  padding: 48px 0;
}
.carousel-wrapper .section-header {
  padding: 0 48px;
}
.carousel-container {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 8px 48px 20px;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.95);
  border: 1px solid var(--color-border);
  box-shadow: 0 2px 12px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: box-shadow 0.2s, opacity 0.2s;
  color: var(--color-dark);
}
.carousel-btn:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.18); }
.carousel-btn.disabled { opacity: 0.3; pointer-events: none; }
.carousel-btn-prev { left: 4px; }
.carousel-btn-next { right: 4px; }
.carousel-btn svg { display: block; flex-shrink: 0; }

/* ===== PRODUCT CARD ===== */
.product-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  text-align: center;
  transition: transform 0.2s;
  position: relative;
}
.product-card:hover { transform: translateY(-2px); }
.product-card .badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: #1d1d1f;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 6px;
  text-transform: uppercase;
}
.product-card .card-image {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  margin-bottom: 16px;
}
.product-card .card-name {
  font-size: 17px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 4px;
  line-height: 1.2;
}
.product-card .card-tagline {
  font-size: 13px;
  color: var(--color-secondary);
  margin-bottom: 12px;
  flex: 1;
  line-height: 1.4;
}
.product-card .card-price {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 2px;
}
.product-card .card-monthly {
  font-size: 12px;
  color: var(--color-secondary);
  margin-bottom: 14px;
}
.card-ctas {
  display: flex;
  gap: 8px;
  justify-content: center;
}
.btn-primary {
  background: var(--color-blue);
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 20px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.btn-primary:hover { background: #0055aa; text-decoration: none; color: #fff; }
.btn-secondary {
  background: transparent;
  color: var(--color-blue);
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 20px;
  border: 1px solid var(--color-blue);
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.btn-secondary:hover { background: rgba(0,102,204,0.05); text-decoration: none; }

/* ===== ACCESSORY CARD ===== */
.accessory-card {
  flex: 0 0 200px;
  background: var(--color-bg);
  border-radius: 14px;
  padding: 20px;
  text-align: center;
  transition: transform 0.2s;
}
.accessory-card:hover { transform: translateY(-2px); }
.accessory-card .card-image {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52px;
  margin-bottom: 12px;
}
.accessory-card .card-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-dark);
  margin-bottom: 6px;
  line-height: 1.3;
}
.accessory-card .card-price {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 10px;
}
.accessory-card .card-note {
  font-size: 11px;
  color: var(--color-secondary);
  margin-bottom: 10px;
}
.btn-small-link {
  font-size: 13px;
  color: var(--color-blue);
  font-weight: 500;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

/* ===== ICON BAR ===== */
.icon-bar {
  background: #fff;
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-inner {
  display: flex;
  align-items: center;
  gap: 0;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px;
}
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  transition: opacity 0.2s;
  flex-shrink: 0;
}
.icon-bar-item:hover { opacity: 0.6; text-decoration: none; }
.icon-bar-icon { font-size: 24px; line-height: 1; }
.icon-bar-label { font-size: 11px; color: var(--color-dark); font-weight: 400; }

/* ===== HELP CARD ===== */
.help-card {
  flex: 0 0 220px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
}
.help-card .card-icon { font-size: 32px; margin-bottom: 14px; }
.help-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 8px; color: var(--color-dark); }
.help-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; flex: 1; }
.help-card .card-link { margin-top: 16px; font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== DIFFERENCE CARD ===== */
.diff-card {
  flex: 0 0 220px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
}
.diff-card .card-icon { font-size: 32px; margin-bottom: 14px; }
.diff-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 8px; color: var(--color-dark); }
.diff-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }

/* ===== INFO GRID ===== */
.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
