/* ===== ORCHARD SHARED STYLES ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-dark: #1d1d1f;
  --color-bg: #f5f5f7;
  --color-secondary: #6e6e73;
  --color-blue: #0066cc;
  --color-white: #ffffff;
  --color-border: #d2d2d7;
  --font-stack: -apple-system, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
}

html { font-size: 16px; scroll-behavior: smooth; }
body {
  font-family: var(--font-stack);
  color: var(--color-dark);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
a { color: var(--color-blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { display: block; max-width: 100%; height: auto; }
button { font-family: var(--font-stack); cursor: pointer; }

/* ===== GLOBAL NAV ===== */
.global-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.07);
}
.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  padding: 0 20px;
  height: 48px;
  gap: 0;
}
.nav-logo {
  display: flex;
  align-items: center;
  color: var(--color-dark);
  margin-right: 20px;
  flex-shrink: 0;
}
.nav-logo:hover { opacity: 0.7; }
.nav-logo svg { display: block; }
.nav-links {
  display: flex;
  align-items: center;
  gap: 0;
  flex: 1;
  justify-content: center;
}
.nav-link {
  font-size: 13px;
  color: var(--color-dark);
  padding: 0 12px;
  line-height: 48px;
  white-space: nowrap;
  transition: opacity 0.2s;
}
.nav-link:hover { opacity: 0.6; text-decoration: none; }
.nav-link.active { font-weight: 500; }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: 20px;
}
.nav-action {
  display: flex;
  align-items: center;
  color: var(--color-dark);
  transition: opacity 0.2s;
}
.nav-action:hover { opacity: 0.6; }

/* ===== SECTION COMMON ===== */
.section-header {
  margin-bottom: 24px;
}
.section-title {
  font-size: 32px;
  font-weight: 700;
  color: var(--color-dark);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.section-subtitle {
  font-size: 17px;
  color: var(--color-secondary);
  margin-top: 6px;
  line-height: 1.4;
}
.section-promo {
  font-size: 14px;
  color: var(--color-secondary);
  margin-top: 10px;
}
.section-promo a { color: var(--color-blue); }

/* ===== CAROUSEL ===== */
.carousel-wrapper {
  position: relative;
  padding: 48px 0;
}
.carousel-wrapper .section-header {
  padding: 0 48px;
}
.carousel-container {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 8px 48px 20px;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.95);
  border: 1px solid var(--color-border);
  box-shadow: 0 2px 12px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: box-shadow 0.2s, opacity 0.2s;
  color: var(--color-dark);
}
.carousel-btn:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.18); }
.carousel-btn.disabled { opacity: 0.3; pointer-events: none; }
.carousel-btn-prev { left: 4px; }
