.save-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.save-card .card-link { font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== FOOTER ===== */
.site-footer {
