}
.model-card .badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: var(--color-dark);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 6px;
