  color: var(--color-secondary);
  margin-bottom: 14px;
}
.card-ctas {
  display: flex;
  gap: 8px;
  justify-content: center;
}
.btn-primary {
  background: var(--color-blue);
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 20px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.btn-primary:hover { background: #0055aa; text-decoration: none; color: #fff; }
.btn-secondary {
  background: transparent;
  color: var(--color-blue);
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border-radius: 20px;
  border: 1px solid var(--color-blue);
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.btn-secondary:hover { background: rgba(0,102,204,0.05); text-decoration: none; }

/* ===== ACCESSORY CARD ===== */
.accessory-card {
  flex: 0 0 200px;
  background: var(--color-bg);
  border-radius: 14px;
  padding: 20px;
  text-align: center;
  transition: transform 0.2s;
}
.accessory-card:hover { transform: translateY(-2px); }
.accessory-card .card-image {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52px;
  margin-bottom: 12px;
}
.accessory-card .card-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-dark);
  margin-bottom: 6px;
  line-height: 1.3;
}
.accessory-card .card-price {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 10px;
}
.accessory-card .card-note {
  font-size: 11px;
  color: var(--color-secondary);
  margin-bottom: 10px;
}
.btn-small-link {
  font-size: 13px;
  color: var(--color-blue);
  font-weight: 500;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

/* ===== ICON BAR ===== */
.icon-bar {
  background: #fff;
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-inner {
  display: flex;
  align-items: center;
  gap: 0;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px;
}
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  transition: opacity 0.2s;
  flex-shrink: 0;
}
.icon-bar-item:hover { opacity: 0.6; text-decoration: none; }
.icon-bar-icon { font-size: 24px; line-height: 1; }
.icon-bar-label { font-size: 11px; color: var(--color-dark); font-weight: 400; }

/* ===== HELP CARD ===== */
.help-card {
  flex: 0 0 220px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
}
.help-card .card-icon { font-size: 32px; margin-bottom: 14px; }
.help-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 8px; color: var(--color-dark); }
.help-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; flex: 1; }
.help-card .card-link { margin-top: 16px; font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== DIFFERENCE CARD ===== */
.diff-card {
  flex: 0 0 220px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
}
.diff-card .card-icon { font-size: 32px; margin-bottom: 14px; }
.diff-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 8px; color: var(--color-dark); }
.diff-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }

/* ===== INFO GRID ===== */
.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px 48px;
}
.info-card {
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px;
}
.info-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.info-card .card-name { font-size: 18px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.info-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }
.info-card .card-link { margin-top: 12px; display: block; font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== SECTION DIVIDER ===== */
.section-divider {
  max-width: 1200px;
  margin: 0 auto;
  border: none;
  border-top: 1px solid var(--color-border);
}

/* ===== CATEGORY PAGE HERO ===== */
.category-hero {
  background: var(--color-bg);
  text-align: center;
  padding: 64px 24px 48px;
  border-bottom: 1px solid var(--color-border);
}
.category-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-dark);
  margin-bottom: 8px;
}
.category-hero p {
  font-size: 21px;
  color: var(--color-secondary);
  max-width: 600px;
  margin: 0 auto;
}

/* ===== SECTION NAV (sticky horizontal) ===== */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 900;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  gap: 0;
  white-space: nowrap;
}
.section-nav-link {
  font-size: 13px;
  color: var(--color-dark);
  padding: 14px 16px;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  display: inline-block;
}
.section-nav-link:hover { color: var(--color-blue); text-decoration: none; }
.section-nav-link.active { color: var(--color-blue); border-bottom-color: var(--color-blue); }

/* ===== STORE HERO ===== */
.store-hero {
  background: var(--color-bg);
  padding: 52px 48px 40px;
  max-width: 1200px;
  margin: 0 auto;
}
.store-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-dark);
  margin-bottom: 6px;
}
.store-hero p {
  font-size: 21px;
  color: var(--color-secondary);
  margin-bottom: 24px;
}
.store-hero-ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.store-hero-cta {
  font-size: 15px;
  color: var(--color-blue);
  font-weight: 500;
  padding: 10px 22px;
  border-radius: 22px;
  background: rgba(0,102,204,0.08);
  transition: background 0.2s;
  text-decoration: none;
}
.store-hero-cta:hover { background: rgba(0,102,204,0.15); text-decoration: none; }

/* ===== QUICK LINKS ===== */
.quick-links-section {
  padding: 48px;
  max-width: 1200px;
  margin: 0 auto;
}
.quick-links-grid {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.quick-link-btn {
  background: var(--color-bg);
  color: var(--color-dark);
  font-size: 15px;
  font-weight: 500;
  padding: 12px 24px;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.quick-link-btn:hover { background: #e8e8ed; text-decoration: none; color: var(--color-dark); }

/* ===== BRAND COLLAB ===== */
.brand-collab {
  background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 100%);
  color: #fff;
  padding: 60px 48px;
  text-align: center;
}
.brand-collab h2 { font-size: 36px; font-weight: 700; margin-bottom: 8px; }
.brand-collab p { font-size: 18px; color: rgba(255,255,255,0.7); margin-bottom: 24px; max-width: 600px; margin-left: auto; margin-right: auto; }
.brand-collab .collab-desc { font-size: 15px; color: rgba(255,255,255,0.55); max-width: 520px; margin: 0 auto 28px; }
.brand-collab a { color: #6cc0ff; font-weight: 500; }

/* ===== SAVINGS SECTION ===== */
.savings-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
}
.savings-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.savings-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.savings-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }
.savings-card .card-link { margin-top: 12px; display: block; font-size: 14px; color: var(--color-blue); }

/* ===== WAYS TO SAVE ===== */
.ways-save-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px 48px;
}
.save-card {
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px;
}
.save-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.save-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.save-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.save-card .card-link { font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
  padding: 40px 0 20px;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px;
}
.footer-legal {
  font-size: 12px;
  color: var(--color-secondary);
  padding-bottom: 24px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 24px;
  line-height: 1.6;
}
.footer-legal p + p { margin-top: 4px; }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 32px 24px;
}
.footer-col-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 12px;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.footer-links a {
  font-size: 13px;
  color: var(--color-secondary);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--color-dark); }

/* ===== MODEL CARD ===== */
.model-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px 24px;
  display: flex;
  flex-direction: column;
  text-align: center;
  position: relative;
}
.model-card .badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: var(--color-dark);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 6px;
  text-transform: uppercase;
}
.model-card .card-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  margin-bottom: 16px;
}
.model-card .card-name { font-size: 19px; font-weight: 600; margin-bottom: 8px; }
.model-card .card-price { font-size: 15px; font-weight: 500; color: var(--color-dark); margin-bottom: 2px; }
.model-card .card-monthly { font-size: 12px; color: var(--color-secondary); margin-bottom: 16px; }
.model-card .card-btn { margin-top: auto; }

/* ===== SHOPPING GUIDE CARD ===== */
.guide-card {
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px;
}
.guide-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.guide-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.guide-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.guide-card .card-link { font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== SPECIAL STORE CARD ===== */
.special-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
}
.special-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.special-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.special-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.special-card .card-link { font-size: 14px; color: var(--color-blue); }

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .store-hero { padding: 36px 20px 28px; }
  .store-hero h1 { font-size: 36px; }
  .carousel-wrapper .section-header { padding: 0 20px; }
  .carousel-track { padding: 8px 20px 20px; }
  .carousel-btn { display: none; }
  .info-grid { padding: 0 20px 32px; }
  .ways-save-grid { padding: 0 20px 32px; }
  .quick-links-section { padding: 32px 20px; }
  .brand-collab { padding: 40px 20px; }
  .footer-inner { padding: 0 20px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px 16px; }

  /* Footer accordion on mobile */
  .footer-col-title {
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .footer-col-title::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform 0.2s;
  }
  .footer-col.open .footer-col-title::after { content: '−'; }
  .footer-col .footer-links { display: none; }
  .footer-col.open .footer-links { display: flex; }

  .category-hero h1 { font-size: 36px; }
  .category-hero p { font-size: 17px; }
  .section-title { font-size: 26px; }
}

@media (max-width: 600px) {
  /* product grid on homepage */
  .product-grid-inner { grid-template-columns: 1fr; }
}

