  margin: 0 auto;
  padding: 0 24px;
  gap: 0;
  white-space: nowrap;
}
.section-nav-link {
  font-size: 13px;
  color: var(--color-dark);
  padding: 14px 16px;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  display: inline-block;
