.store-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-dark);
  margin-bottom: 6px;
}
.store-hero p {
  font-size: 21px;
  color: var(--color-secondary);
  margin-bottom: 24px;
}
.store-hero-ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.store-hero-cta {
  font-size: 15px;
  color: var(--color-blue);
  font-weight: 500;
  padding: 10px 22px;
  border-radius: 22px;
  background: rgba(0,102,204,0.08);
  transition: background 0.2s;
  text-decoration: none;
}
.store-hero-cta:hover { background: rgba(0,102,204,0.15); text-decoration: none; }

/* ===== QUICK LINKS ===== */
.quick-links-section {
  padding: 48px;
  max-width: 1200px;
  margin: 0 auto;
}
.quick-links-grid {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.quick-link-btn {
  background: var(--color-bg);
  color: var(--color-dark);
  font-size: 15px;
  font-weight: 500;
  padding: 12px 24px;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  text-decoration: none;
  display: inline-block;
}
.quick-link-btn:hover { background: #e8e8ed; text-decoration: none; color: var(--color-dark); }

/* ===== BRAND COLLAB ===== */
.brand-collab {
  background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 100%);
  color: #fff;
  padding: 60px 48px;
  text-align: center;
}
.brand-collab h2 { font-size: 36px; font-weight: 700; margin-bottom: 8px; }
.brand-collab p { font-size: 18px; color: rgba(255,255,255,0.7); margin-bottom: 24px; max-width: 600px; margin-left: auto; margin-right: auto; }
.brand-collab .collab-desc { font-size: 15px; color: rgba(255,255,255,0.55); max-width: 520px; margin: 0 auto 28px; }
