}
.savings-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.savings-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.savings-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }
