  margin: 0 auto;
  padding: 0 48px 48px;
}
.save-card {
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px;
}
.save-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.save-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.save-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.save-card .card-link { font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
