}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px;
}
.footer-legal {
  font-size: 12px;
  color: var(--color-secondary);
  padding-bottom: 24px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 24px;
  line-height: 1.6;
}
.footer-legal p + p { margin-top: 4px; }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 32px 24px;
}
.footer-col-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 12px;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.footer-links a {
  font-size: 13px;
  color: var(--color-secondary);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--color-dark); }

/* ===== MODEL CARD ===== */
.model-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px 24px;
  display: flex;
  flex-direction: column;
  text-align: center;
  position: relative;
}
.model-card .badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: var(--color-dark);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 6px;
  text-transform: uppercase;
}
.model-card .card-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  margin-bottom: 16px;
}
.model-card .card-name { font-size: 19px; font-weight: 600; margin-bottom: 8px; }
.model-card .card-price { font-size: 15px; font-weight: 500; color: var(--color-dark); margin-bottom: 2px; }
.model-card .card-monthly { font-size: 12px; color: var(--color-secondary); margin-bottom: 16px; }
.model-card .card-btn { margin-top: auto; }

/* ===== SHOPPING GUIDE CARD ===== */
.guide-card {
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px;
}
.guide-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.guide-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.guide-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.guide-card .card-link { font-size: 14px; color: var(--color-blue); font-weight: 500; }

/* ===== SPECIAL STORE CARD ===== */
.special-card {
  flex: 0 0 240px;
  background: var(--color-bg);
  border-radius: 16px;
  padding: 28px 24px;
}
.special-card .card-icon { font-size: 28px; margin-bottom: 14px; }
.special-card .card-name { font-size: 17px; font-weight: 600; margin-bottom: 6px; color: var(--color-dark); }
.special-card .card-desc { font-size: 14px; color: var(--color-secondary); line-height: 1.5; margin-bottom: 12px; }
.special-card .card-link { font-size: 14px; color: var(--color-blue); }

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .store-hero { padding: 36px 20px 28px; }
  .store-hero h1 { font-size: 36px; }
  .carousel-wrapper .section-header { padding: 0 20px; }
  .carousel-track { padding: 8px 20px 20px; }
  .carousel-btn { display: none; }
  .info-grid { padding: 0 20px 32px; }
  .ways-save-grid { padding: 0 20px 32px; }
  .quick-links-section { padding: 32px 20px; }
  .brand-collab { padding: 40px 20px; }
  .footer-inner { padding: 0 20px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px 16px; }

  /* Footer accordion on mobile */
  .footer-col-title {
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .footer-col-title::after {
    content: '+';
    font-size: 18px;
    font-weight: 300;
    transition: transform 0.2s;
  }
  .footer-col.open .footer-col-title::after { content: '−'; }
  .footer-col .footer-links { display: none; }
  .footer-col.open .footer-links { display: flex; }

  .category-hero h1 { font-size: 36px; }
  .category-hero p { font-size: 17px; }
  .section-title { font-size: 26px; }
}

@media (max-width: 600px) {
  /* product grid on homepage */
  .product-grid-inner { grid-template-columns: 1fr; }
}

